// Morning briefing delivery. Shared state lives in process.env.STATE_DIR (read on every call).
import os from "node:os";
import path from "node:path";

function stateDir() {
  return process.env.STATE_DIR || path.join(os.tmpdir(), "bot-state");
}

function toMs(now) {
  if (now instanceof Date) return now.getTime();
  if (typeof now === "number") return now;
  return Date.parse(now);
}

const BRIEFING = "briefing";

export async function deliver({ user, candidate, now, transport, consentStore }) {
  const dir = stateDir();
  const nowMs = toMs(now);
  const type = candidate.type;
  const held = (reason, resumeAt = null) => ({ push: false, inApp: false, reason, resumeAt });

  // Same message id, same answer: a finished delivery is never repeated.
  const key = `deliver-${user.id}-${candidate.id}`;
  const done = gkRead(dir, key);
  if (done) return done;

  // Consent: false or absent means off. A store that is down means unknown, so hold.
  let consents;
  try {
    consents = await consentStore.get(user.id);
  } catch {
    return held("Consent could not be checked right now, so nothing was sent.");
  }
  if (!consents || consents[type] !== true) {
    return held(`The user has not consented to ${type} notifications.`);
  }

  // Category chosen in notification settings. Briefing is asked for, so a missing choice allows it; other cards need a yes.
  const choice = user.categories ? user.categories[type] : undefined;
  if (choice === false || (choice === undefined && type !== BRIEFING)) {
    return held(choice === false
      ? `The user switched ${type} notifications off in notification settings.`
      : `The user never chose to receive ${type} notifications.`);
  }

  // Push-only holds: the in-app item is silent and still goes out.
  let pushReason = null;
  let resumeAt = null;
  if (user.notificationsPermitted === false) {
    pushReason = "Push was withheld because notifications are not permitted in the phone's settings.";
  } else if (user.snoozedUntil != null) {
    const until = Date.parse(user.snoozedUntil);
    if (Number.isNaN(until)) {
      pushReason = "Push was withheld because the snooze time could not be read.";
    } else if (until > nowMs) {
      pushReason = "Push was withheld because the user snoozed notifications.";
      resumeAt = new Date(until).toISOString();
    }
  }

  // Claim before sending. Keep the claim once anything may have left.
  if (!gkClaim(dir, key)) {
    return gkRead(dir, key) || held("This message is already being delivered by another worker.");
  }

  let push = false;
  let inApp = false;
  let reason = pushReason;
  if (!pushReason) {
    try {
      push = (await transport.push(user, candidate)) === true;
      if (!push) reason = "The phone did not accept the push (for example no device token).";
    } catch {
      reason = "The push may or may not have been sent; the outcome is unknown.";
    }
  }
  try {
    await transport.inApp(user, candidate);
    inApp = true;
  } catch {
    reason = (reason ? reason + " " : "") + "The in-app item could not be stored.";
  }
  const result = { push, inApp, reason, resumeAt };
  gkWrite(dir, key, result);
  return result;
}

export async function recordDismissal(userId, type, now) {
  const dir = stateDir();
  const ms = toMs(now);
  gkCount(dir, `dismissals-${userId}-${type}`, Number.MAX_SAFE_INTEGER);
  gkWrite(dir, `dismissed-last-${userId}-${type}`, {
    at: Number.isNaN(ms) ? null : new Date(ms).toISOString(),
  });
}
EOF
